contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint128 vBase, uint128 vNft, uint16 initFeeRate, uint16 newFeeRate) public {
        c.initialize(address(0x1), address(0x2), vBase, vNft, 0, initFeeRate, bytes32(0), false, false);
        bool reverted;
        try c.setFeeRate(newFeeRate) { reverted = false; } catch { reverted = true; }
        assert((newFeeRate > 5000) ? (reverted && c.feeRate() == initFeeRate) : (!reverted && c.feeRate() == newFeeRate));
    }
}

