    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address baseToken,
        address nft,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 badFeeRate,
        uint16 goodFeeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        require(badFeeRate > 5000);
        require(goodFeeRate <= 5000);

        bool reverted1;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, badFeeRate, merkleRoot, useOracle, payRoy) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        bool reverted2;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, goodFeeRate, merkleRoot, useOracle, payRoy) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        assert(
            reverted1 &&
            !reverted2 &&
            !c.initialized() == false &&
            c.baseToken() == baseToken &&
            c.nft() == nft &&
            c.virtualBaseTokenReserves() == vBase &&
            c.virtualNftReserves() == vNft &&
            c.changeFee() == changeFee &&
            c.feeRate() == goodFeeRate &&
            c.merkleRoot() == merkleRoot &&
            c.useStolenNftOracle() == useOracle &&
            c.payRoyalties() == payRoy
        );
    }
}

