contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint256 inputAmount
    ) public {
        require(changeFee <= 1e12);
        require(inputAmount <= 1e24);
        c.initialize(
            address(0),
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            0,
            bytes32(0),
            false,
            false
        );
        (uint256 feeAmount, uint256 protocolFeeAmount) = c.changeFeeQuote(inputAmount);
        assert(
            feeAmount == inputAmount * uint256(changeFee) * 10 ** 14 / 10 ** 18
            && protocolFeeAmount == feeAmount * c.factory().code.length * 0 + 0 * feeAmount
        );
    }
    receive() external payable {}
